package com.hrcoresystem.hrcore_api.common.pagination;
import org.springframework.data.domain.*;
public final class OffsetPageable implements Pageable { private final long offset; private final int size; private final Sort sort; public OffsetPageable(long offset,int size,Sort sort){if(offset<0||size<1)throw new IllegalArgumentException("Invalid pagination");this.offset=offset;this.size=size;this.sort=sort==null?Sort.unsorted():sort;} public int getPageNumber(){return (int)Math.min(Integer.MAX_VALUE,offset/size);} public int getPageSize(){return size;} public long getOffset(){return offset;} public Sort getSort(){return sort;} public Pageable next(){return new OffsetPageable(offset+size,size,sort);} public Pageable previousOrFirst(){return offset<=0?first():new OffsetPageable(Math.max(0,offset-size),size,sort);} public Pageable first(){return new OffsetPageable(0,size,sort);} public Pageable withPage(int pageNumber){if(pageNumber<0)throw new IllegalArgumentException("Page index must not be less than zero");return new OffsetPageable((long)pageNumber*size,size,sort);} public boolean hasPrevious(){return offset>0;} }
